SELECT result_tags AS tags, timestamp AS timestamp, value AS value FROM (SELECT lhs.original_group AS result_tags, lhs.timestamp AS timestamp, lhs.value AS value FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (
    SELECT series.tags AS tags, max(d.timestamp) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
        SELECT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {lhs_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64})
    ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags
)) AS lhs INNER JOIN (SELECT join_group, toUInt8(1) AS present_marker FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (
    SELECT series.tags AS tags, max(d.timestamp) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
        SELECT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {rhs_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64})
    ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags
)) AS rhs GROUP BY join_group) AS rhs ON lhs.join_group = rhs.join_group) AS joined_rows ORDER BY result_tags
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
